337	        let worker = parse(&["tool", "serve", "worker", "--help"]).unwrap_err();
338	        assert_eq!(worker.kind(), ErrorKind::DisplayHelp);
339	        let worker = worker.to_string();
340	        for needle in [
341	            "--port",
342	            "--http",
343	            "--https",
344	            "mutually exclusive with --https",
345	            "mutually exclusive with --http",
346	            "--config",
347	        ] {
348	            assert!(worker.contains(needle), "worker help missing {needle}:\n{worker}");
349	        }
350	        assert!(!worker.contains("--profile"), "{worker}");
351	        assert!(!worker.contains("--strict"), "{worker}");
352	
353	        let check = parse(&["tool", "check", "--help"]).unwrap_err();
354	        assert_eq!(check.kind(), ErrorKind::DisplayHelp);
355	        let check = check.to_string();
356	        for needle in ["--strict", "--config", "--define"] {
357	            assert!(check.contains(needle), "check help missing {needle}:\n{check}");
358	        }
359	        for absent in ["--profile", "--port", "--http"] {
360	            assert!(!check.contains(absent), "check help leaks {absent}:\n{check}");
361	        }
362	    }
363	
364	    #[test]
365	    fn global_position_swap_keeps_help_and_errors_stable() {
366	        let baseline = parse(&["tool", "--config", "x.toml", "serve", "worker", "--help"])
367	            .unwrap_err()
368	            .to_string();
369	        let swapped = parse(&["tool", "serve", "worker", "--config", "x.toml", "--help"])
370	            .unwrap_err()
371	            .to_string();
372	        assert_eq!(baseline, swapped);
373	
374	        let baseline = parse(&["tool", "--config", "x.toml", "serve", "worker"]).unwrap_err();
375	        let swapped = parse(&["tool", "serve", "worker", "--config", "x.toml"]).unwrap_err();
376	        assert_eq!(baseline.kind(), swapped.kind());
377	        assert_eq!(baseline.to_string(), swapped.to_string());
378	    }
379	}
